import bpy, os
from mathutils import Vector
expected=os.path.normcase(os.path.normpath(r'C:\mcp-blender\salvador_lacerda_do_zero.blend'))
if os.path.normcase(os.path.normpath(bpy.data.filepath))!=expected: raise RuntimeError('arquivo errado')
bands={'LOW':[],'MID':[],'HIGH':[],'SPAN':[]}
for o in bpy.context.scene.objects:
 if o.type not in {'MESH','CURVE','FONT'} or o.hide_viewport: continue
 try:
  ps=[o.matrix_world@Vector(c) for c in o.bound_box]; z0=min(p.z for p in ps); z1=max(p.z for p in ps)
 except: continue
 rec=(o.name,round(z0,2),round(z1,2),[c.name for c in o.users_collection])
 if z0<8 and z1>32: bands['SPAN'].append(rec)
 elif z0>=32: bands['HIGH'].append(rec)
 elif z1<=12: bands['LOW'].append(rec)
 else: bands['MID'].append(rec)
for k in ('LOW','MID','HIGH','SPAN'):
 print(f'[{k}] count={len(bands[k])}')
 for r in bands[k][:40]: print(r)
print('VERTICAL_WORLD_BANDS_OK')
